import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/theme/app_colors.dart';import '../../../core/theme/app_typography.dart';import '../../../core/widgets/app_button.dart';import '../../../models/stylist_model.dart';import '../../../providers/branch_provider.dart';import '../../../providers/stylist_provider.dart';class AdminStylistsTab extends StatefulWidget {  const AdminStylistsTab({super.key});  @override  State<AdminStylistsTab> createState() => _AdminStylistsTabState();}class _AdminStylistsTabState extends State<AdminStylistsTab> {  String _selectedBranchFilter = 'All';  void _showStylistDialog(BuildContext context, {StylistModel? stylist}) {    final branchProv = context.read<BranchProvider>();    final nameCtrl = TextEditingController(text: stylist?.name ?? '');    final bioCtrl = TextEditingController(text: stylist?.bio ?? '');    final expCtrl = TextEditingController(text: stylist?.experience ?? '');    final specCtrl = TextEditingController(text: stylist?.specialization ?? '');    String? selectedBranchId = stylist?.branchId;    if (selectedBranchId == '') selectedBranchId = null;    showDialog(      context: context,      builder: (ctx) => StatefulBuilder(        builder: (context, setState) => AlertDialog(          title: Text(stylist == null ? 'Add Stylist' : 'Edit Stylist'),          content: SingleChildScrollView(            child: Column(              mainAxisSize: MainAxisSize.min,              children: [                TextField(controller: nameCtrl, decoration: const InputDecoration(labelText: 'Name')),                DropdownButtonFormField<String?>(                  value: selectedBranchId,                  decoration: const InputDecoration(labelText: 'Assign Branch'),                  items: branchProv.branches.map((b) => DropdownMenuItem(                    value: b.branchId,                    child: Text(b.name),                  )).toList(),                  onChanged: (val) => setState(() => selectedBranchId = val),                ),                TextField(controller: specCtrl, decoration: const InputDecoration(labelText: 'Specialization')),                TextField(controller: expCtrl, decoration: const InputDecoration(labelText: 'Experience (e.g. 5+ Years)')),                TextField(controller: bioCtrl, decoration: const InputDecoration(labelText: 'Bio')),              ],            ),          ),          actions: [            TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),            AppButton(              label: 'Save',              height: 38,              onPressed: () async {                if (nameCtrl.text.isNotEmpty && selectedBranchId != null) {                  final branchName = branchProv.branches.firstWhere((b) => b.branchId == selectedBranchId).name;                  final newStylist = StylistModel(                    stylistId: stylist?.stylistId ?? 'stylist_${DateTime.now().millisecondsSinceEpoch}',                    name: nameCtrl.text.trim(),                    branchId: selectedBranchId!,                    branchName: branchName,                    bio: bioCtrl.text.trim(),                    experience: expCtrl.text.trim(),                    specialization: specCtrl.text.trim(),                    profileImage: stylist?.profileImage ?? 'https://images.unsplash.com/photo-1595152772835-219674b2a8a6?w=500',                    isActive: stylist?.isActive ?? true,                    rating: stylist?.rating ?? 4.9,                    totalReviews: stylist?.totalReviews ?? 0,                    services: stylist?.services ?? [],                    availability: stylist?.availability ?? [],                  );                  await context.read<StylistProvider>().saveStylist(newStylist);                  if (ctx.mounted) Navigator.of(ctx).pop();                }              },            ),          ],        ),      ),    );  }  void _toggleStylistStatus(BuildContext context, StylistModel stylist) {    showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: Text(stylist.isActive ? 'Deactivate Stylist?' : 'Activate Stylist?'),        content: Text(          stylist.isActive              ? 'Are you sure you want to deactivate ${stylist.name}? They will no longer be bookable.'              : 'Are you sure you want to activate ${stylist.name}?',        ),        actions: [          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),          AppButton(            label: 'Confirm',            height: 38,            onPressed: () async {              final updated = StylistModel(                stylistId: stylist.stylistId,                name: stylist.name,                branchId: stylist.branchId,                branchName: stylist.branchName,                bio: stylist.bio,                experience: stylist.experience,                specialization: stylist.specialization,                profileImage: stylist.profileImage,                isActive: !stylist.isActive,                rating: stylist.rating,                totalReviews: stylist.totalReviews,                services: stylist.services,                availability: stylist.availability,              );              await context.read<StylistProvider>().saveStylist(updated);              if (ctx.mounted) Navigator.of(ctx).pop();            },          ),        ],      ),    );  }  @override  Widget build(BuildContext context) {    final stylistProv = context.watch<StylistProvider>();    final branchProv = context.watch<BranchProvider>();    final stylistList = stylistProv.stylists.where((s) {      if (_selectedBranchFilter == 'All') return true;      return s.branchId == _selectedBranchFilter;    }).toList();    return Scaffold(      body: Column(        children: [          Padding(            padding: const EdgeInsets.all(16.0),            child: DropdownButtonFormField<String>(              value: _selectedBranchFilter,              decoration: const InputDecoration(labelText: 'Filter by Branch'),              items: [                const DropdownMenuItem(value: 'All', child: Text('All Branches')),                ...branchProv.branches.map((b) => DropdownMenuItem(                      value: b.branchId,                      child: Text(b.name),                    )),              ],              onChanged: (val) {                if (val != null) setState(() => _selectedBranchFilter = val);              },            ),          ),          Expanded(            child: ListView.builder(              padding: const EdgeInsets.symmetric(horizontal: 16),              itemCount: stylistList.length,              itemBuilder: (ctx, i) {                final stylist = stylistList[i];                return Card(                  margin: const EdgeInsets.only(bottom: 12),                  child: ListTile(                    leading: CircleAvatar(                      backgroundImage: NetworkImage(stylist.profileImage),                    ),                    title: Text(                      stylist.name,                      style: AppTypography.titleMedium.copyWith(                        color: stylist.isActive ? AppColors.textPrimary : Colors.grey,                      ),                    ),                    subtitle: Text('${stylist.specialization}\nBranch: ${stylist.branchName}'),                    trailing: PopupMenuButton<String>(                      onSelected: (val) {                        if (val == 'edit') {                          _showStylistDialog(context, stylist: stylist);                        } else if (val == 'toggle') {                          _toggleStylistStatus(context, stylist);                        }                      },                      itemBuilder: (ctx) => [                        const PopupMenuItem(value: 'edit', child: Text('Edit')),                        PopupMenuItem(                          value: 'toggle',                          child: Text(stylist.isActive ? 'Deactivate' : 'Activate'),                        ),                      ],                    ),                    isThreeLine: true,                  ),                );              },            ),          ),        ],      ),      floatingActionButton: FloatingActionButton.extended(        backgroundColor: AppColors.primary,        foregroundColor: Colors.white,        onPressed: () => _showStylistDialog(context),        icon: const Icon(Icons.add),        label: const Text('Add Stylist'),      ),    );  }}